wa3_urls = []
existing_wa = {county: authority for county, authority in wa_links}
for county, data in WA3_COUNTIES.items():
    sources = [('Washington State Department of Health — Onsite Sewage Systems', WA3_STATE_ROLE)] + data['sources']
    sections = [
        ('Washington local-health-jurisdiction framework', 'Washington State Department of Health assigns property-level onsite sewage permitting and management to local health jurisdictions. County or district rules and procedures can be more specific than the statewide minimums.')
    ] + data['sections']
    url = write_county_page(
        'Washington', 'washington', county,
        data['authority'], data['contact'], sections, sources,
        verified=data.get('verified', 'August 29, 2026')
    )
    wa3_urls.append(url)
    existing_wa[county] = data['authority']

wa_links[:] = sorted(existing_wa.items())
write_hub(
    'Washington', 'washington', wa_links,
    'Washington delegates onsite sewage system permitting and management to local health jurisdictions. SepticScope adds counties only after the responsible local agency and meaningful local requirements are validated from government sources.',
    'This Washington set now includes 15 verified counties. Local design, installer, inspection, repair, operating-permit, and building-clearance requirements are documented county-by-county rather than inferred statewide.'
)

county_index = OUTPUT / 'counties' / 'index.html'
if county_index.exists():
    text = county_index.read_text(encoding='utf-8')
    text = text.replace('Browse 9 verified Washington county septic guides →', 'Browse 15 verified Washington county septic guides →')
    county_index.write_text(text, encoding='utf-8')

sitemap = OUTPUT / 'sitemap.xml'
if sitemap.exists():
    sm = sitemap.read_text(encoding='utf-8')
else:
    sm = '<?xml version="1.0" encoding="UTF-8"?><urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9"></urlset>'
entries = ''.join(f'<url><loc>{u}</loc><lastmod>2026-08-31</lastmod></url>' for u in wa3_urls if u not in sm)
if entries:
    sm = sm.replace('</urlset>', entries + '</urlset>')
    sitemap.write_text(sm, encoding='utf-8')

print(f'Washington third expansion complete: +{len(wa3_urls)} verified county guides')
exec((ROOT / 'washington_fourth_expansion.py').read_text(encoding='utf-8'), globals())
